[{"order":1,"type":"heading","text":"SSL Pinning and Network Security Config in Android (Java)"},{"order":2,"type":"paragraph","text":"Network security is a critical aspect of Android application development. By default, Android apps trust the system's certificate store, which can expose your app to Man-in-the-Middle (MitM) attacks. SSL Pinning ensures that your app only communicates with servers possessing a specific, trusted certificate or public key."},{"order":3,"type":"subheading","text":"Step 1: Create the Network Security Configuration XML"},{"order":4,"type":"paragraph","text":"Starting from Android 7.0 (API level 24), Android provides a declarative Network Security Configuration file. Create a new XML file named network_security_config.xml inside your res/xml/ directory."},{"order":5,"type":"code","text":"<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <domain-config cleartextTrafficPermitted="false">
        <domain includeSubdomains="true">api.yourdomain.com</domain>
        <pin-set expiration="2026-01-01">
            <pin digest="SHA-256">Base64EncodedCertificateHashHere=</pin>
            <pin digest="SHA-256">BackupBase64EncodedHashHere=</pin>
        </pin-set>
    </domain-config>
</network-security-config>"},{"order":6,"type":"subheading","text":"Step 2: Reference the Configuration in AndroidManifest.xml"},{"order":7,"type":"paragraph","text":"Next, link your newly created network security configuration file to your application within the AndroidManifest.xml file using the android:networkSecurityConfig attribute."},{"order":8,"type":"code","text":"<application
    android:name=".MyApplication"
    android:allowBackup="false"
    android:icon="@mipmap/ic_launcher"
    android:label="@string/app_name"
    android:networkSecurityConfig="@xml/network_security_config"
    android:theme="@style/Theme.AppCompat.Light.DarkActionBar">

    <activity android:name=".MainActivity">
        <intent-filter>
            <action android:name="android.intent.action.MAIN" />
            <category android:name="android.intent.category.LAUNCHER" />
        </intent-filter>
    </activity>
</application>"},{"order":9,"type":"subheading","text":"Step 3: Programmatic SSL Pinning with OkHttp (Java)"},{"order":10,"type":"paragraph","text":"If you are supporting older Android versions (below API 24) or need more granular control over network requests in Java, you can implement SSL pinning using OkHttp and CertificatePinner."},{"order":11,"type":"code","text":"import okhttp3.CertificatePinner;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import java.io.IOException;

public class NetworkClient {
    private static OkHttpClient client;

    public static OkHttpClient getClient() {
        if (client == null) {
            CertificatePinner certificatePinner = new CertificatePinner.Builder()
                .add("api.yourdomain.com", "sha256/Base64EncodedCertificateHashHere=")
                .build();

            client = new OkHttpClient.Builder()
                .certificatePinner(certificatePinner)
                .build();
        }
        return client;
    }
}"},{"order":12,"type":"subheading","text":"Best Practices and Considerations"},{"order":13,"type":"bullet_point","text":"Always provide a backup pin in case your primary certificate changes or gets compromised."},{"order":14,"type":"bullet_point","text":"Handle CertificateException gracefully in your network calls to prevent app crashes when pinning fails."},{"order":15,"type":"bullet_point","text":"Remember to update your pins before your server certificates expire."}]
